<!--
 * 知识图谱管理
 *
 * 主页面，包含三个 Tab：搜索、统计、摄取。
 * <p>消费后端 KnowledgeGraphController 契约（auto-generated by bash/gen-contract.py）。
 *
 * @path apps/agent-web/src/views/knowledge-graph/index.vue
 * @author ydsz-team
 * @since 1.0.0
-->
<script lang="ts" setup>
/**
 * 知识图谱管理主页面
 *
 * @author ydsz-team
 * @since 1.0.0
 */
import { YdEmptyState } from '@ydsz-core/ydsz-ui';
import { Page, useI18n } from '@ydsz/common-ui';
import { computed, ref } from 'vue';
import {
  ElAlert,
  ElButton,
  ElCard,
  ElCol,
  ElEmpty,
  ElIcon,
  ElInput,
  ElMessage,
  ElOption,
  ElProgress,
  ElRow,
  ElSelect,
  ElStatistic,
  ElTable,
  ElTableColumn,
  ElTabPane,
  ElTabs,
  ElTag,
  ElUpload,
} from 'element-plus';
import { Refresh, Search, UploadFilled, View } from '@element-plus/icons-vue';
import { ingest, querySubgraph, searchEntities, stats } from '#/api/knowledgeGraph';
import EntityDetailDrawer from './entity-detail-drawer.vue';
import GraphView from './graph-view.vue';
import type { GraphNode, GraphRelation } from './graph-view.vue';

defineOptions({ name: 'KnowledgeGraphManagement' });

const { t } = useI18n();

// Tab 状态
type TabName = 'search' | 'graph' | 'stats' | 'ingest';
const activeTab = ref<TabName>('search');

// ===== 搜索 Tab 状态 =====
const searchQuery = ref<string>('');
const entityTypeOptions = ref<{ label: string; value: string }[]>([
  { label: '全部类型', value: '' },
  { label: 'Person', value: 'Person' },
  { label: 'Organization', value: 'Organization' },
  { label: 'Location', value: 'Location' },
  { label: 'Event', value: 'Event' },
  { label: 'Product', value: 'Product' },
]);
const selectedType = ref<string>('');
const searchLoading = ref<boolean>(false);
const searchResults = ref<Record<string, unknown>[]>([]);
const hasSearched = ref<boolean>(false);

// ===== 统计 Tab 状态 =====
const statsLoading = ref<boolean>(false);
const graphStats = ref<Record<string, number>>({});

// ===== 摄取 Tab 状态 =====
const ingestLoading = ref<boolean>(false);
const ingestProgress = ref<number>(0);
const ingestResult = ref<string>('');
const ingestError = ref<string>('');
const ingestFileName = ref<string>('');

// ===== 图视图 Tab 状态 =====
const graphLoading = ref<boolean>(false);
const graphError = ref<string>('');
const graphNodes = ref<GraphNode[]>([]);
const graphRelations = ref<GraphRelation[]>([]);
const selectedGraphEntityId = ref<string>('');

// ===== 详情抽屉 =====
const detailDrawerVisible = ref<boolean>(false);
const selectedEntityId = ref<string>('');

/**
 * 搜索实体
 */
async function handleSearch(): Promise<void> {
  if (!searchQuery.value.trim()) {
    ElMessage.warning(t('knowledgeGraph.search.keywordRequired') || '请输入搜索关键词');
    return;
  }
  searchLoading.value = true;
  hasSearched.value = true;
  try {
    const results = await searchEntities({
      query: searchQuery.value,
      depth: selectedType.value ? undefined : undefined,
    });
    searchResults.value = (results ?? []) as Record<string, unknown>[];
  } catch {
    searchResults.value = [];
    ElMessage.error(t('knowledgeGraph.search.failed') || '搜索失败');
  } finally {
    searchLoading.value = false;
  }
}

/**
 * 加载统计数据
 */
async function loadStats(): Promise<void> {
  statsLoading.value = true;
  try {
    const data = await stats();
    graphStats.value = data ?? {};
  } catch {
    graphStats.value = {};
    ElMessage.error(t('knowledgeGraph.stats.failed') || '加载统计信息失败');
  } finally {
    statsLoading.value = false;
  }
}

/**
 * Tab 切换处理
 */
function handleTabChange(name: TabName): void {
  activeTab.value = name;
  if (name === 'stats' && Object.keys(graphStats.value).length === 0) {
    void loadStats();
  }
  if (name === 'graph' && graphNodes.value.length === 0) {
    void loadDefaultGraph();
  }
}

/**
 * 加载默认图数据（图谱统计中的节点和关系概览）
 * 如果有搜索结果，用搜索结果中第一个实体的子图；否则尝试使用统计中的数据。
 */
async function loadDefaultGraph(): Promise<void> {
  graphLoading.value = true;
  graphError.value = '';
  try {
    // 如果有搜索结果，取第一个节点的子图
    if (searchResults.value.length > 0 && searchResults.value[0].entityId) {
      await loadSubgraph(String(searchResults.value[0].entityId));
      return;
    }
    // 无搜索结果时显示空图，由用户点击节点触发加载
    graphNodes.value = [];
    graphRelations.value = [];
  } catch {
    graphError.value = t('knowledgeGraph.graph.loadFailed') || '加载图谱数据失败';
    graphNodes.value = [];
    graphRelations.value = [];
  } finally {
    graphLoading.value = false;
  }
}

/**
 * 加载指定实体的子图
 */
async function loadSubgraph(entityId: string): Promise<void> {
  if (!entityId) return;
  graphLoading.value = true;
  graphError.value = '';
  selectedGraphEntityId.value = entityId;
  try {
    const data = await querySubgraph({ entityId }, { depth: 2 });
    if (data && typeof data === 'object') {
      const d = data as Record<string, unknown>;
      const nodesRaw = d.nodes;
      const relationsRaw = d.relations;
      graphNodes.value = (Array.isArray(nodesRaw) ? nodesRaw : []) as unknown as GraphNode[];
      graphRelations.value = (Array.isArray(relationsRaw) ? relationsRaw : []) as unknown as GraphRelation[];
    } else {
      graphNodes.value = [];
      graphRelations.value = [];
    }
  } catch {
    graphError.value = t('knowledgeGraph.graph.loadFailed') || '加载图谱数据失败';
    graphNodes.value = [];
    graphRelations.value = [];
  } finally {
    graphLoading.value = false;
  }
}

/**
 * 图视图节点点击事件
 */
function handleGraphNodeClick(node: GraphNode): void {
  if (node.entityId) {
    void loadSubgraph(node.entityId);
  }
}

/**
 * 查看详情
 */
function handleViewDetail(row: Record<string, unknown>): void {
  selectedEntityId.value = String(row.entityId ?? '');
  detailDrawerVisible.value = true;
}

/**
 * 文件上传前处理
 */
function handleBeforeUpload(file: { name: string }): void {
  ingestFileName.value = file.name;
  ingestResult.value = '';
  ingestError.value = '';
  ingestProgress.value = 0;
  return true;
}

/**
 * 文件上传成功
 */
async function handleUploadSuccess(response: unknown): Promise<void> {
  ingestProgress.value = 100;
  ingestResult.value = t('knowledgeGraph.ingest.success') || '摄取成功';
  ElMessage.success(t('knowledgeGraph.ingest.success') || '摄取成功');
}

/**
 * 文件上传失败
 */
function handleUploadError(error: unknown): void {
  ingestError.value = (error as Error)?.message || (t('knowledgeGraph.ingest.failed') || '摄取失败');
  ElMessage.error(ingestError.value);
}

/**
 * 手动触发摄取
 */
async function handleIngest(): Promise<void> {
  if (!ingestFileName.value) {
    ElMessage.warning(t('knowledgeGraph.ingest.selectFile') || '请先选择文件');
    return;
  }
  ingestLoading.value = true;
  ingestProgress.value = 50;
  try {
    await ingest({ fileName: ingestFileName.value });
    ingestProgress.value = 100;
    ingestResult.value = t('knowledgeGraph.ingest.success') || '摄取成功';
    ElMessage.success(t('knowledgeGraph.ingest.success') || '摄取成功');
  } catch {
    ingestError.value = t('knowledgeGraph.ingest.failed') || '摄取失败';
    ingestProgress.value = 0;
  } finally {
    ingestLoading.value = false;
  }
}

// 统计卡片数据
const statCards = computed(() => [
  { label: t('knowledgeGraph.stats.totalEntities') || '实体总数', value: graphStats.value.totalEntities ?? graphStats.value.entityCount ?? 0, color: 'primary' },
  { label: t('knowledgeGraph.stats.totalRelations') || '关系总数', value: graphStats.value.totalRelations ?? graphStats.value.relationCount ?? 0, color: 'purple' },
  { label: t('knowledgeGraph.stats.entityTypes') || '实体类型数', value: graphStats.value.entityTypes ?? graphStats.value.typeCount ?? 0, color: 'blue' },
  { label: t('knowledgeGraph.stats.ingestJobs') || '摄取任务数', value: graphStats.value.ingestJobs ?? graphStats.value.jobCount ?? 0, color: 'green' },
]);

// 类型分布饼图数据
const typeDistData = computed(() => {
  const dist = graphStats.value.typeDistribution;
  if (!dist) return [];
  try {
    const obj = typeof dist === 'string' ? JSON.parse(dist) : dist;
    return Object.entries(obj).map(([name, value]) => ({ name, value: Number(value) }));
  } catch {
    return [];
  }
});
</script>

<template>
  <Page auto-content-height>
    <div class="space-y-4">
      <!-- 页面标题 -->
      <div class="flex items-center justify-between">
        <h2 class="text-lg font-semibold text-text-primary">
          {{ $t('knowledgeGraph.title') || '知识图谱管理' }}
        </h2>
        <ElButton
          v-if="activeTab === 'stats'"
          :icon="Refresh"
          @click="loadStats"
        >
          {{ $t('common.refresh') || '刷新' }}
        </ElButton>
      </div>

      <!-- Tab 切换 -->
      <ElTabs
        v-model="activeTab"
        @tab-change="handleTabChange"
      >
        <!-- 搜索 Tab -->
        <ElTabPane :label="$t('knowledgeGraph.tab.search') || '实体搜索'" name="search">
          <div class="space-y-4 pt-4">
            <!-- 搜索栏 -->
            <div class="flex items-center gap-3">
              <ElInput
                v-model="searchQuery"
                :placeholder="$t('knowledgeGraph.search.placeholder') || '输入关键词搜索实体...'"
                clearable
                style="width: 320px;"
                @keyup.enter="handleSearch"
              >
                <template #prefix>
                  <ElIcon><Search /></ElIcon>
                </template>
              </ElInput>
              <ElSelect
                v-model="selectedType"
                :placeholder="$t('knowledgeGraph.search.entityType') || '实体类型'"
                clearable
                style="width: 180px;"
              >
                <ElOption
                  v-for="opt in entityTypeOptions"
                  :key="opt.value"
                  :label="opt.label"
                  :value="opt.value"
                />
              </ElSelect>
              <ElButton
                type="primary"
                :loading="searchLoading"
                @click="handleSearch"
              >
                {{ $t('common.search') || '搜索' }}
              </ElButton>
            </div>

            <!-- 搜索结果表格 -->
            <ElCard
              v-loading="searchLoading"
              shadow="never"
            >
              <template v-if="hasSearched && searchResults.length === 0 && !searchLoading">
                <YdEmptyState
                  :description="$t('knowledgeGraph.search.noResults') || '未找到匹配的实体'"
                  preset="search"
                  title=""
                />
              </template>
              <ElTable
                v-else
                :data="searchResults"
                stripe
                style="width: 100%;"
              >
                <ElTableColumn
                  prop="entityId"
                  :label="$t('knowledgeGraph.search.entityId') || 'EntityID'"
                  width="200"
                  show-overflow-tooltip
                />
                <ElTableColumn
                  prop="name"
                  :label="$t('knowledgeGraph.search.name') || '名称'"
                  min-width="160"
                  show-overflow-tooltip
                />
                <ElTableColumn
                  prop="type"
                  :label="$t('knowledgeGraph.search.type') || '类型'"
                  width="130"
                >
                  <template #default="{ row }">
                    <ElTag
                      size="small"
                      :type="(row.type || row.entityType) === 'Person' ? 'primary' : 'info'"
                    >
                      {{ row.type || row.entityType || '-' }}
                    </ElTag>
                  </template>
                </ElTableColumn>
                <ElTableColumn
                  prop="description"
                  :label="$t('knowledgeGraph.search.description') || '描述'"
                  min-width="200"
                  show-overflow-tooltip
                />
                <ElTableColumn
                  :label="$t('common.operation') || '操作'"
                  width="120"
                  fixed="right"
                >
                  <template #default="{ row }">
                    <ElButton
                      type="primary"
                      link
                      size="small"
                      :icon="View"
                      @click="handleViewDetail(row)"
                    >
                      {{ $t('common.view') || '查看' }}
                    </ElButton>
                  </template>
                </ElTableColumn>
              </ElTable>
            </ElCard>
          </div>
        </ElTabPane>

        <!-- 图视图 Tab -->
        <ElTabPane :label="$t('knowledgeGraph.tab.graph') || '图视图'" name="graph">
          <div class="space-y-4 pt-4">
            <ElCard
              v-loading="graphLoading"
              shadow="never"
            >
              <GraphView
                :nodes="graphNodes"
                :relations="graphRelations"
                :loading="graphLoading"
                :error="graphError"
                @refresh="loadDefaultGraph"
                @node-click="handleGraphNodeClick"
              />
            </ElCard>
          </div>
        </ElTabPane>

        <!-- 统计 Tab -->
        <ElTabPane :label="$t('knowledgeGraph.tab.stats') || '图谱统计'" name="stats">
          <div class="space-y-4 pt-4">
            <!-- 统计卡片 -->
            <ElRow
              :gutter="16"
              v-loading="statsLoading"
            >
              <ElCol
                v-for="card in statCards"
                :key="card.label"
                :span="6"
              >
                <ElCard
                  shadow="never"
                  class="stat-card"
                >
                  <ElStatistic
                    :value="card.value"
                    :title="card.label"
                  />
                </ElCard>
              </ElCol>
            </ElRow>

            <!-- 空态 -->
            <ElCard
              v-if="!statsLoading && Object.keys(graphStats).length === 0"
              shadow="never"
            >
              <YdEmptyState
                :description="$t('knowledgeGraph.stats.noData') || '暂无统计数据'"
                preset="data"
                title=""
              />
            </ElCard>
          </div>
        </ElTabPane>

        <!-- 摄取 Tab -->
        <ElTabPane :label="$t('knowledgeGraph.tab.ingest') || '图谱摄取'" name="ingest">
          <div class="space-y-4 pt-4">
            <ElCard shadow="never">
              <div class="space-y-4">
                <!-- 描述文字 -->
                <p class="text-sm text-text-secondary">
                  {{ $t('knowledgeGraph.ingest.description') || '上传结构化数据文件（JSON/JSONL/CSV）以导入知识图谱。' }}
                </p>

                <!-- 文件上传 -->
                <ElUpload
                  :before-upload="handleBeforeUpload"
                  :on-success="handleUploadSuccess"
                  :on-error="handleUploadError"
                  :show-file-list="false"
                  accept=".json,.jsonl,.csv"
                  drag
                  action="/api/v1/agent/knowledge/ingest"
                >
                  <ElIcon
                    class="el-icon--upload"
                    size="48"
                  >
                    <UploadFilled />
                  </ElIcon>
                  <div class="el-upload__text">
                    {{ $t('knowledgeGraph.ingest.dragText') || '拖拽文件到此处或' }}
                    <em>{{ $t('knowledgeGraph.ingest.clickText') || '点击上传' }}</em>
                  </div>
                  <template #tip>
                    <div class="el-upload__tip">
                      {{ $t('knowledgeGraph.ingest.formats') || '支持 JSON / JSONL / CSV 格式' }}
                    </div>
                  </template>
                </ElUpload>

                <!-- 上传中进度 -->
                <div
                  v-if="ingestLoading || ingestProgress > 0"
                  class="space-y-2"
                >
                  <p class="text-sm text-text-secondary">
                    {{ ingestFileName }}
                  </p>
                  <ElProgress
                    :percentage="ingestProgress"
                    :status="ingestProgress === 100 ? 'success' : ''"
                  />
                </div>

                <!-- 结果提示 -->
                <ElAlert
                  v-if="ingestResult"
                  :title="ingestResult"
                  type="success"
                  show-icon
                  :closable="true"
                  @close="ingestResult = ''"
                />
                <ElAlert
                  v-if="ingestError"
                  :title="ingestError"
                  type="error"
                  show-icon
                  :closable="true"
                  @close="ingestError = ''"
                />
              </div>
            </ElCard>
          </div>
        </ElTabPane>
      </ElTabs>

      <!-- 实体详情抽屉 -->
      <EntityDetailDrawer
        v-if="detailDrawerVisible"
        v-model="detailDrawerVisible"
        :entity-id="selectedEntityId"
      />
    </div>
  </Page>
</template>

<style scoped>
:deep(.el-tabs__nav-wrap) {
  padding-left: 0;
}

:deep(.stat-card .el-statistic__content) {
  font-size: 28px;
  font-weight: 600;
}

:deep(.stat-card .el-statistic__title) {
  font-size: 13px;
  color: var(--text-tertiary, #6b7280);
}

:deep(.stat-card) {
  text-align: center;
}
</style>
